// Body mesh decode and shape math. Pure: no scene or app state here.
// `body.js` (generated by tools/mesh.py) holds the base mesh, index buffers,
// landmark vertices and the sparse MakeHuman shape targets.
import { BODY_BASE, BODY_IDX, BODY_IDX_GENITAL, COUNTS, MARKS, EYES, LIPS, TARGETS } from './body.js';

export function b64(s, Type) {
  const bin = atob(s);
  const u = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) u[i] = bin.charCodeAt(i);
  return new Type(u.buffer);
}

// Decoded once at module load. Vertex order: body, eyes, genital helper.
export const BASE = b64(BODY_BASE, Float32Array);
export const INDEX = b64(BODY_IDX, Uint16Array); // body + eyes
const GENITAL = b64(BODY_IDX_GENITAL, Uint16Array);
export const INDEX_ALL = new Uint16Array(INDEX.length + GENITAL.length);
INDEX_ALL.set(INDEX); INDEX_ALL.set(GENITAL, INDEX.length);
export const LIPS_MASK = b64(LIPS, Uint8Array);
export { COUNTS, MARKS, EYES };

const T = {};
for (const k of Object.keys(TARGETS)) T[k] = { i: b64(TARGETS[k].i, Uint16Array), d: b64(TARGETS[k].d, Int16Array), s: TARGETS[k].s };

function add(out, key, w) {
  const t = T[key]; if (!t || !w) return;
  const f = t.s * w, I = t.i, D = t.d;
  for (let j = 0, k = 0; j < I.length; j++, k += 3) { const o = I[j] * 3; out[o] += D[k] * f; out[o + 1] += D[k + 1] * f; out[o + 2] += D[k + 2] * f; }
}
// Stand on the floor, 1.75 units tall. Real-world size comes from the height setting.
function normalise(out) {
  let lo = Infinity, hi = -Infinity; for (let i = 1; i < out.length; i += 3) { if (out[i] < lo) lo = out[i]; if (out[i] > hi) hi = out[i]; }
  const k = 1.75 / (hi - lo); for (let i = 0; i < out.length; i += 3) { out[i] *= k; out[i + 1] = (out[i + 1] - lo) * k; out[i + 2] *= k; }
  return out;
}
const clamp = (v, a, b) => Math.min(b, Math.max(a, v));
const maleness = (fig) => (fig === 'male' ? 1 : fig === 'female' ? 0 : 0.5);
// Split a 0..1 value (0.5 = average) into weights for the min / average / max targets.
const axis = (v) => { v = clamp(v, 0, 1); return v < 0.5 ? { min: 1 - 2 * v, ave: 2 * v, max: 0 } : { min: 0, ave: 2 - 2 * v, max: 2 * v - 1 }; };
const CELLS = ['min', 'ave', 'max'];

// The un-morphed MakeHuman base. v47 backups store their anchors on this shape.
export function legacyPositions() { return normalise(new Float32Array(BASE)); }

let macroKey = '', macroCache = null;
// Gender blend plus MakeHuman's muscle x weight grid (bilinear, 0.5 = average).
function macro(fig, muscle, weight) {
  const key = fig + '|' + muscle + '|' + weight;
  if (key !== macroKey) {
    const out = new Float32Array(BASE); const gm = maleness(fig);
    add(out, 'male', gm); add(out, 'female', 1 - gm);
    const mu = axis(muscle), we = axis(weight);
    for (const [g, gw] of [['m', gm], ['f', 1 - gm]]) for (const a of CELLS) for (const b of CELLS) if (a !== 'ave' || b !== 'ave') add(out, `${g}_${a}_${b}`, gw * mu[a] * we[b]);
    macroKey = key; macroCache = out;
  }
  return macroCache;
}

// Full shape for a project state: { figure, muscle 0..1, weight 0..1, fit: { key: -1..1 } }.
export function shapePositions(s) {
  const fig = s.figure || 'male';
  const out = new Float32Array(macro(fig, s.muscle ?? 0.5, s.weight ?? 0.5));
  const fit = s.fit || {};
  for (const k of Object.keys(fit)) {
    const v = clamp(+fit[k] || 0, -1, 1); if (!v || k === 'cup' || k === 'firm') continue;
    add(out, k + (v > 0 ? '1' : '0'), Math.abs(v));
  }
  const fem = 1 - maleness(fig);
  if (fem > 0 && (fit.cup || fit.firm)) {
    const cu = axis(0.5 + 0.5 * (+fit.cup || 0)), fi = axis(0.5 + 0.5 * (+fit.firm || 0));
    for (const a of CELLS) for (const b of CELLS) if (a !== 'ave' || b !== 'ave') add(out, `cup_${a}_${b}`, fem * cu[a] * fi[b]);
  }
  return normalise(out);
}

// The shape the first prototype saved against (muscle 0..1 from average, weight -1..1).
// Only used to re-anchor tattoos when an old save is opened.
export function shapePositionsV1(fig, muscle, weight) {
  const out = new Float32Array(BASE); const gm = maleness(fig), m = muscle || 0, w = weight || 0;
  add(out, 'male', gm); add(out, 'female', 1 - gm);
  add(out, 'm_max_ave', gm * m); add(out, 'f_max_ave', (1 - gm) * m);
  if (w > 0) { add(out, 'm_ave_max', gm * w); add(out, 'f_ave_max', (1 - gm) * w); } else if (w < 0) { add(out, 'm_ave_min', gm * -w); add(out, 'f_ave_min', (1 - gm) * -w); }
  return normalise(out);
}
